#include "Config.h"
#include <fstream>
namespace Enchant { static Config g_cfg;
static bool val(const std::string&s){return s=="1"||s=="true"||s=="TRUE"||s=="yes";}
static void setv(const std::string&k,const std::string&v){if(k=="Enabled")g_cfg.enabled=val(v);else if(k=="AutoEvents")g_cfg.autoEvents=val(v);else if(k=="AmbientAudio")g_cfg.ambientAudio=val(v);else if(k=="NpcReactions")g_cfg.npcReactions=val(v);else if(k=="VehicleReactions")g_cfg.vehicleReactions=val(v);else if(k=="CameraEffects")g_cfg.cameraEffects=val(v);else if(k=="WorldEffects")g_cfg.worldEffects=val(v);else if(k=="Notifications")g_cfg.notifications=val(v);else if(k=="StoryModeOnly")g_cfg.storyModeOnly=val(v);else if(k=="ToggleKey")g_cfg.toggleKey=std::stoi(v);else if(k=="MinDelayMs")g_cfg.minDelayMs=std::stoi(v);else if(k=="MaxDelayMs")g_cfg.maxDelayMs=std::stoi(v);else if(k=="CooldownMs")g_cfg.cooldownMs=std::stoi(v);else if(k=="Intensity")g_cfg.intensity=std::stoi(v);else if(k=="MaxEventDistance")g_cfg.maxEventDistance=std::stof(v);}
Config& ConfigManager::Get(){return g_cfg;}
void ConfigManager::Load(const std::string&path){std::ifstream f(path);if(!f)return;std::string line;while(std::getline(f,line)){auto p=line.find_first_not_of(" \t\r");if(p==std::string::npos)continue;line=line.substr(p);if(line.empty()||line[0]=='#'||line[0]==';'||line[0]=='[')continue;auto eq=line.find('=');if(eq!=std::string::npos)setv(line.substr(0,eq),line.substr(eq+1));}}
void ConfigManager::Save(const std::string&path){auto&c=g_cfg;std::ofstream f(path);f<<"[Engine]\nEnabled="<<c.enabled<<"\nAutoEvents="<<c.autoEvents<<"\nMinDelayMs="<<c.minDelayMs<<"\nMaxDelayMs="<<c.maxDelayMs<<"\nIntensity="<<c.intensity<<"\nCooldownMs="<<c.cooldownMs<<"\n\n[Events]\nAmbientAudio="<<c.ambientAudio<<"\nNpcReactions="<<c.npcReactions<<"\nVehicleReactions="<<c.vehicleReactions<<"\nCameraEffects="<<c.cameraEffects<<"\nWorldEffects="<<c.worldEffects<<"\nNotifications="<<c.notifications<<"\n\n[Safety]\nStoryModeOnly="<<c.storyModeOnly<<"\nMaxEventDistance="<<c.maxEventDistance<<"\n";}}
